import fs from 'node:fs/promises'
import {dir,db,asset,send,reviewed} from './late-reply-runtime-20261006.mjs'
const s=JSON.parse(await fs.readFile(dir+'/late-review.json','utf8'))
const plans=[]
function add(name,body,extra={}){const c=s.contacts.find(c=>c.name===name),thread=s.touches.filter(t=>t.contact_id===c.id);plans.push({id:c.id,name,phone:c.phone,city:c.city,latest:thread.at(-1).id,from:thread.filter(t=>t.direction==='inbound'&&t.channel==='sms').at(-1).metadata.to,body,...extra})}
add('VIDUR ARORA',"Absolutely, Vidur. For jobs you refer to us, we can offer $100-$150 per job valued at $2,000 or less, and $200-$300 per job above $2,000. Would that work for you?",{note:'Owner explicitly approved these referral ranges for Vidur. Offered exactly; awaiting acceptance. No payout timing or additional conditions invented.'})
add('FAN YANG',"Here you go, Fan! Our Toronto card is attached. Feel free to keep it handy and share it with clients when they need moving help.",{media_urls:[await asset('Toronto')]})
const mark=s.contacts.find(c=>c.name==='Mark Paul Deklerk');if(!mark.notes.includes('source_key=realtor-ca:2243435'))throw Error('Source changed')
add('Mark Paul Deklerk',"Hi Mark! I found your business contact details through your public REALTOR.ca agent profile. Here's our Toronto card as requested, with our contact information for you to keep handy.",{media_urls:[await asset('Toronto')],note:'Answered number-source question from recorded REALTOR.ca provenance and supplied requested card.'})
add('RASHED MAHMOOD BUTT',"Here you go, Rashed! Our Mississauga card is attached. Clients can call or text 437-782-3004 or email mississauga@starmovers.ca for a moving quote. Feel free to save it and pass it along.",{media_urls:[await asset('Mississauga')]})
add('Charlene Longlade',"We have business cards for visitors to take and digital cards you can share, Charlene. I've noted 11 am and about eight people for the College Avenue open house, plus business cards for your display. Thanks for offering to set them out!",{note:'Acknowledged 11 am, approximately eight people, and request for display materials. Physical cards and food still require owner fulfilment.'})
const card=await asset('Halton Hills')
add('MICHELLE BELL',`Hi Michelle,\n\nThanks for sending your email address. Here's our Halton Hills digital card for your files:\n${card}\n\nWe help with moves in Halton Hills and surrounding areas, as well as the wider GTA and Hamilton. Feel free to forward the card when a client needs moving help.\n\nClients can call or text 437-782-3004 or email haltonhills@starmovers.ca for a quote. We provide binding estimates once the move details are confirmed, based on inventory, route, access and any packing needed.\n\nWebsite: https://starmovers.ca\n\nLooking forward to working together,\nJohn Owolabi\nSaturn Star Movers`,{channel:'email',email:'michelle@sellwithbell.ca',subject:'Your Saturn Star Movers details - Halton Hills',note:'Requested company details and correct-city card link emailed via SES; recipient-supplied email saved.'})
await fs.writeFile(dir+'/late-plan.json',JSON.stringify(plans,null,2))
if(!process.argv.includes('--send')){console.log(JSON.stringify(plans,null,2));process.exit(0)}
for(const p of plans.filter(p=>p.channel!=='email'))await send(p)
const vidur=s.contacts.find(c=>c.name==='VIDUR ARORA');const [vt]=await db('crm_tasks',{id:'eq.evening-20261006-vidur-referral-terms'});await db('crm_tasks',{id:'eq.'+vt.id},'PATCH',{title:'Vidur referral fee offered — await acceptance',description:vt.description+'\n\nOwner approval October 6: $100-$150 per referred job valued at $2,000 or below; $200-$300 for jobs above $2,000. Exact ranges sent in current conversation. Await Vidur acceptance. Exact amount within each range, payment timing and tax basis were not specified; do not invent them.',status:'open',owner_name:'John'});
const [vc]=await db('market_contacts',{id:'eq.'+vidur.id});await db('market_contacts',{id:'eq.'+vidur.id},'PATCH',{notes:(vc.notes||'')+'\n[Owner-approved Vidur referral proposal 2026-10-06] $100-$150 per job at $2,000 or below; $200-$300 above $2,000. Sent; recipient acceptance pending. Other settlement details not yet specified.'});
const [ct]=await db('crm_tasks',{id:'eq.open-house-pizza-20261006-6dcd0274-62c6-47be-8a81-7c22d0d634c8'});await db('crm_tasks',{id:'eq.'+ct.id},'PATCH',{title:'Charlene: Oct 10, 11 am — pizza for ~8 and display cards',description:ct.description+'\n\n[Latest recipient confirmation] October 10 at 11:00 am, 683 College Avenue, Woodstock. Approximately eight people (4-5 groups). Asked for promotional material and offered to display it. Replied explaining business/digital cards; physical business cards added to plan. Food preferences still unspecified. No food ordered; owner must arrange delivery/materials.',owner_name:'John',status:'open'});
const patsy=s.contacts.find(c=>c.name==='Patricia Graham');const [pc]=await db('market_contacts',{id:'eq.'+patsy.id});await db('market_contacts',{id:'eq.'+pc.id,name:'eq.Patricia Graham'},'PATCH',{name:'Patsy Graham',notes:(pc.notes||'')+'\n[2026-10-06 recipient preference] Goes by Patsy. Original imported name Patricia Graham retained here.'});
for(const c of s.contacts){const thread=s.touches.filter(t=>t.contact_id===c.id),last=thread.at(-1);if(last?.direction!=='inbound'||plans.some(p=>p.id===c.id))continue;const [fresh]=await db('market_touches',{contact_id:'eq.'+c.id,order:'created_at.desc,id.desc',limit:'1'});if(fresh.id!==last.id)continue;await reviewed(last.id,c.id===patsy.id?'Preferred name Patsy saved. Acknowledgement needs no additional outbound.':'Thanks, reaction or saved-contact acknowledgement reviewed; no additional outbound needed. Existing follow-through remains open.');}
console.log(JSON.stringify({sms_sent:5,email_prepared:1,patsy_name_saved:true}))
